print("Examining each string pair to see what str.replace can achieve:")
print()

for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Pair {i}: '{inp}' -> '{outp}'")

    if inp == outp:
        print("  No change needed")
    else:
        # Look at differences character by character
        diff_positions = []
        for j, (c1, c2) in enumerate(zip(inp, outp)):
            if c1 != c2:
                diff_positions.append((j, c1, c2))

        if len(outp) != len(inp):
            print(f"  Length change: {len(inp)} -> {len(outp)}")

        if diff_positions:
            print(f"  Differences at positions: {diff_positions}")

        # Try to find patterns that could be replaced
        # Check if there are substrings that match
        if len(inp) >= 2 and len(outp) >= 2:
            # Check for 2-character patterns
            for length in range(2, min(len(inp), len(outp)) + 1):
                for start in range(len(inp) - length + 1):
                    pattern = inp[start:start+length]
                    if pattern in outp:
                        # See if replacing this pattern gives us the right result
                        temp_result = inp.replace(pattern, outp[outp.find(pattern):outp.find(pattern)+length])
                        if temp_result == outp:
                            print(f"  Could potentially use pattern '{pattern}' -> '{outp[outp.find(pattern):outp.find(pattern)+length]}'")

    print()

print("Key insight: The only clear replacement is 'yk' -> 'xuh' for pair 2")
print("For pair 1, there's no simple pattern that works with str.replace()")
